import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'pg-idx-l4-001', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'B-tree Internals', question: 'What is the "suffix truncation" optimization in B-tree internal (branch) pages?', options: ['Removing the last column', 'PostgreSQL truncates the trailing key columns in internal pages since they only need enough information to direct searches, saving space', 'Truncating long strings', 'Removing trailing NULLs'], correctAnswer: 1, explanation: 'B-tree internal pages only need to separate left/right children. PostgreSQL truncates suffix columns that are not needed for routing, packing more entries per internal page and reducing tree depth.', tags: ['suffix-truncation', 'b-tree', 'internal-pages'] },
  { id: 'pg-idx-l4-002', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'B-tree Internals', question: 'What is the "high key" concept in PostgreSQL B-tree pages?', options: ['The highest value in the table', 'Each B-tree page stores the exclusive upper bound of its key range, enabling efficient concurrent access', 'The key with highest cardinality', 'The maximum index entry'], correctAnswer: 1, explanation: 'The high key is the exclusive upper bound of a B-tree page, part of the Lehman-Yao algorithm. It allows concurrent readers to know they have reached the end of a page\'s range without locking the parent.', tags: ['high-key', 'lehman-yao', 'concurrent-access'] },
  { id: 'pg-idx-l4-003', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'B-tree Internals', question: 'How does B-tree deduplication interact with UNIQUE indexes?', options: ['Deduplication is used for unique indexes too', 'Deduplication is disabled for UNIQUE indexes since they have no duplicate keys to compress', 'It doubles the unique constraint', 'UNIQUE indexes use special deduplication'], correctAnswer: 1, explanation: 'UNIQUE indexes cannot have duplicate keys (by definition), so deduplication has no entries to compress. It only benefits non-unique B-tree indexes with repeated key values.', tags: ['deduplication', 'unique-index', 'not-applicable'] },
  { id: 'pg-idx-l4-004', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'B-tree Vacuum', question: 'What is the "B-tree vacuum" cycle and how does it differ from heap VACUUM?', options: ['They are the same', 'B-tree vacuum removes dead TIDs from index pages and recycles empty pages; this runs as part of VACUUM after heap dead tuple identification', 'B-tree vacuum is separate', 'B-tree does not need vacuuming'], correctAnswer: 1, explanation: 'VACUUM first scans the heap for dead tuples, collects their TIDs, then removes those TIDs from every index. Empty index pages are recycled via the freelist.', tags: ['b-tree-vacuum', 'dead-tids', 'recycling'] },
  { id: 'pg-idx-l4-005', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'GIN Internals', question: 'What is the "consistent" support function in GIN?', options: ['A consistency check', 'A function that tells GIN whether a candidate row matches the query, given which index keys the row contains', 'A data integrity function', 'A replication function'], correctAnswer: 1, explanation: 'The consistent function is called for each candidate row to determine if it matches the query. For JSONB @>, it checks if the row\'s keys/values contain the query\'s keys/values.', tags: ['gin', 'consistent-function', 'support-function'] },
  { id: 'pg-idx-l4-006', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'GiST Internals', question: 'What is the "penalty" function in GiST and why does it matter for index quality?', options: ['A performance penalty', 'It measures the cost of inserting a new entry into a subtree, guiding GiST to minimize bounding box expansion and overlap', 'A function that penalizes bad queries', 'A cost-based function'], correctAnswer: 1, explanation: 'The penalty function determines which subtree best accommodates a new entry. Poor penalty implementations lead to overlapping bounding boxes, causing more subtrees to be searched during queries.', tags: ['gist', 'penalty-function', 'index-quality'] },
  { id: 'pg-idx-l4-007', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'GiST Internals', question: 'What is the "picksplit" function in GiST?', options: ['A function to split queries', 'A function that decides how to divide entries between two pages during a page split, critical for search performance', 'A function to pick the best index', 'A parallel split function'], correctAnswer: 1, explanation: 'When a GiST page overflows, picksplit determines how to distribute entries between the two resulting pages. A good split minimizes overlap and dead space in the bounding boxes.', tags: ['gist', 'picksplit', 'page-split'] },
  { id: 'pg-idx-l4-008', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Custom Index', question: 'Can you create custom index access methods in PostgreSQL?', options: ['No, only built-in types', 'Yes, using the Table Access Method and Index Access Method APIs to implement custom storage and indexing', 'Only with C extensions', 'Only by modifying source code'], correctAnswer: 1, explanation: 'PostgreSQL\'s extensibility allows custom index access methods via C extensions. You implement required support functions (insert, scan, vacuum, etc.) and register them with CREATE ACCESS METHOD.', tags: ['custom-am', 'extensibility', 'c-extension'] },
  { id: 'pg-idx-l4-009', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'How does the planner estimate the cost of an Index Scan?', options: ['Fixed cost per row', 'Estimates: (startup cost for tree descent) + (per-page random I/O cost × estimated pages) + (per-tuple CPU cost × estimated rows)', 'Count of matching rows only', 'Based on index size only'], correctAnswer: 1, explanation: 'Index Scan cost = startup cost (B-tree descent, O(log N)) + random_page_cost × estimated pages to read + cpu_index_tuple_cost × index tuples + cpu_tuple_cost × heap tuples.', tags: ['cost-estimation', 'planner-internals', 'index-scan-cost'] },
  { id: 'pg-idx-l4-010', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is the "Mackert-Lohman" formula used for in PostgreSQL?', options: ['Join cost estimation', 'Estimating the number of distinct heap pages that need to be fetched for a given number of index tuples, considering random I/O clustering', 'Selectivity estimation', 'Memory allocation'], correctAnswer: 1, explanation: 'The Mackert-Lohman formula estimates how many distinct heap pages need to be read given N index tuples spread across T total pages. It accounts for the clustering effect.', tags: ['mackert-lohman', 'page-estimation', 'clustering'] },
  { id: 'pg-idx-l4-011', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Parallel Index', question: 'What is "parallel-aware" hash join for index building?', options: ['Hash join with index', 'Parallel workers cooperatively build a shared hash table during parallel index creation, using shared memory', 'Building indexes in parallel hash', 'A hash-based index build'], correctAnswer: 1, explanation: 'Parallel B-tree index build uses a shared/private memory split where workers sort their portions, then the leader performs a multi-way merge to build the final index.', tags: ['parallel-build', 'shared-memory', 'cooperative'] },
  { id: 'pg-idx-l4-012', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'B-tree', question: 'What is "bottom-up index deletion" (PostgreSQL 14) and how does it prevent page splits?', options: ['Deleting from leaf to root', 'When a page is about to split, PostgreSQL first checks if any dead tuples can be removed from the page to free space, avoiding the split', 'Deleting the bottom of the tree', 'Removing the lowest-valued entries'], correctAnswer: 1, explanation: 'Before splitting a full page, PostgreSQL checks if dead index tuples (from deleted/updated rows) can be removed. If enough space is freed, the split is avoided, reducing bloat.', tags: ['bottom-up-deletion', 'split-avoidance', 'postgresql-14'] },
  { id: 'pg-idx-l4-013', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'BRIN Advanced', question: 'What is "BRIN bloom" operator class (PostgreSQL 14)?', options: ['A BRIN variant using bloom filters', 'A BRIN operator class that stores a bloom filter per block range instead of min/max, supporting equality queries efficiently', 'BRIN for bloom indexes', 'A compressed BRIN'], correctAnswer: 0, explanation: 'BRIN bloom stores a bloom filter per page range. This supports equality (=) lookups on columns that are NOT physically sorted, unlike minmax which requires correlation.', codeSnippet: 'CREATE INDEX idx_email_brin ON users\nUSING brin (email brin_bloom_ops)\nWITH (pages_per_range = 32);', tags: ['brin-bloom', 'equality', 'no-correlation'] },
  { id: 'pg-idx-l4-014', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'GIN Advanced', question: 'What is "GIN fast scan" optimization?', options: ['A faster GIN scan mode', 'For AND queries with multiple posting lists, GIN uses a skip-scan approach on sorted TID lists to find common TIDs efficiently', 'GIN index compression', 'A parallel GIN scan'], correctAnswer: 1, explanation: 'For multi-key GIN queries (e.g., JSONB @> with multiple keys), GIN performs a merge-intersection on sorted posting lists. It skips ahead in longer lists to match positions in shorter ones.', tags: ['gin-fast-scan', 'posting-list', 'merge-intersection'] },
  { id: 'pg-idx-l4-015', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is the "selectivity estimation" for complex boolean expressions?', options: ['Simple multiplication', 'The planner recursively estimates selectivity: AND = s1 × s2 (assuming independence), OR = s1 + s2 - s1×s2, NOT = 1 - s', 'Only for simple conditions', 'Using sampling'], correctAnswer: 1, explanation: 'For complex WHERE conditions, the planner combines individual selectivities using probability rules. The independence assumption can cause significant errors for correlated columns.', tags: ['selectivity', 'boolean-estimation', 'independence'] },
  { id: 'pg-idx-l4-016', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'How does the planner estimate n_distinct for join column cardinality?', options: ['Always n_distinct of the smaller table', 'Uses the minimum n_distinct of the two join columns as an upper bound on the number of output groups', 'Maximum of both tables', 'Always assumes 1000'], correctAnswer: 1, explanation: 'For equi-joins, the estimated output n_distinct is bounded by the minimum of the two columns\' n_distinct values. This affects GROUP BY and DISTINCT estimates on join results.', tags: ['n-distinct', 'join-cardinality', 'estimation'] },
  { id: 'pg-idx-l4-017', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Index Maintenance', question: 'What is the "index_cleanup" storage parameter?', options: ['Automatically cleaning indexes', 'A per-table setting that controls whether VACUUM performs index cleanup; disabling it speeds up VACUUM but causes index bloat', 'Index garbage collection', 'Cleaning index files'], correctAnswer: 1, explanation: 'ALTER TABLE ... SET (vacuum_index_cleanup = off) tells VACUUM to skip index cleanup. Useful for emergency VACUUM of critically bloated tables when you need to freeze XIDs fast.', codeSnippet: 'ALTER TABLE big_table SET (vacuum_index_cleanup = off);', tags: ['vacuum-index-cleanup', 'storage-parameter', 'emergency'] },
  { id: 'pg-idx-l4-018', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Index Design', question: 'What is the optimal fillfactor for a B-tree index on a frequently updated table?', options: ['100% (maximum packing)', '70-90% to leave room for HOT updates and reduce page splits', '50%', '10%'], correctAnswer: 1, explanation: 'Lower fillfactor (70-90%) leaves free space per page. Updated rows can be placed in the same page (HOT update) if no indexed column changed, avoiding page splits and new index entries.', tags: ['fillfactor', 'hot-updates', 'page-splits'] },
  { id: 'pg-idx-l4-019', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is "index path generation" in the query planner?', options: ['Creating new indexes', 'The planner generates candidate access paths for each table including seq scan, index scan per index, bitmap scan, etc., and selects the cheapest', 'Generating index definitions', 'Building index paths'], correctAnswer: 1, explanation: 'For each relation, the planner generates all possible access paths: sequential scan, one index scan per usable index, bitmap scans combining indexes, etc. It costs each and keeps the cheapest.', tags: ['path-generation', 'planner-internals', 'access-methods'] },
  { id: 'pg-idx-l4-020', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'B-tree Advanced', question: 'What is the "posting list" format in B-tree deduplication (PG 13)?', options: ['A list of posts', 'A single index entry containing the key value and an array of TIDs, stored more compactly than separate entries per TID', 'A mailing list format', 'A WAL entry format'], correctAnswer: 1, explanation: 'Deduplicated B-tree entries store one key value with a sorted TID array. This eliminates key repetition overhead (typically 8+ bytes per duplicate), significantly compacting the index.', tags: ['posting-list', 'deduplication', 'compact-storage'] },
  { id: 'pg-idx-l4-021', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'GiST Advanced', question: 'Why might a GiST index scan visit many more pages than a B-tree scan for the same selectivity?', options: ['GiST is buggy', 'GiST bounding boxes can overlap, causing the search to descend into multiple branches even when only one contains matches', 'GiST has larger pages', 'GiST does not cache pages'], correctAnswer: 1, explanation: 'Unlike B-tree (which has strict key separation between children), GiST internal nodes may have overlapping bounding boxes. A query may need to check multiple branches, increasing I/O.', tags: ['gist', 'overlap', 'multi-path-search'] },
  { id: 'pg-idx-l4-022', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the interaction between index scans and "buffer pinning"?', options: ['No interaction', 'Index scans pin buffer pages in shared memory while reading them, preventing eviction; long-running index scans can cause buffer pressure', 'Pins improve index performance', 'Only for sequential scans'], correctAnswer: 1, explanation: 'Each page read during an index scan is "pinned" in shared_buffers. Pin counts prevent the page from being evicted. Many concurrent index scans on different pages can pressure the buffer pool.', tags: ['buffer-pinning', 'shared-buffers', 'pressure'] },
  { id: 'pg-idx-l4-023', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is the "pathkey" concept in the planner?', options: ['A key to the plan', 'An abstraction representing a sort ordering that a path can provide, used for matching ORDER BY requirements and merge join inputs', 'A path in the file system', 'A key in the index'], correctAnswer: 1, explanation: 'Pathkeys represent sort orderings. The planner matches pathkeys from index scans against ORDER BY, merge join, and GROUP BY requirements to avoid unnecessary sorts.', tags: ['pathkey', 'sort-ordering', 'planner-internals'] },
  { id: 'pg-idx-l4-024', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Custom Operator', question: 'What functions must you provide to create a custom B-tree operator class?', options: ['Only an equality function', 'Five comparison functions: less, less-equal, equal, greater-equal, greater; plus a support function for comparison', 'Only less-than and greater-than', 'Any two functions'], correctAnswer: 1, explanation: 'A B-tree operator class needs 5 strategy operators (< <= = >= >) plus support function 1 (the comparison function that returns -1/0/1). Optional: in_range, equalimage.', tags: ['operator-class', 'b-tree', 'strategy-functions'] },
  { id: 'pg-idx-l4-025', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'BRIN Advanced', question: 'What is the "desummarization" and "resummarization" process for BRIN?', options: ['Removing and recreating summaries', 'Clearing outdated BRIN range summaries that contain deleted data and recalculating them from current heap pages', 'Summarizing index data', 'Converting BRIN to B-tree'], correctAnswer: 0, explanation: 'When significant data changes in a range, the BRIN summary may become too broad. Desummarize removes the stale summary; the next summarization pass recalculates it from current data.', codeSnippet: 'SELECT brin_desummarize_range(\'idx_brin\', 128);\nSELECT brin_summarize_range(\'idx_brin\', 128);', tags: ['brin', 'desummarization', 'accuracy'] },
  { id: 'pg-idx-l4-026', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'How does the planner handle "parameterized" index scans in the context of nested loop joins?', options: ['It always uses parameterized scans', 'The planner generates parameterized paths with outer-variable clauses moved to the index condition, computing cost per-loop', 'Parameterized scans are not allowed', 'Only with prepared statements'], correctAnswer: 1, explanation: 'For nested loop joins, the planner creates parameterized paths where the outer table provides a value used in the inner index scan. Cost is estimated as: (per-loop index scan cost) × (expected loops).', tags: ['parameterized', 'nested-loop', 'cost-per-loop'] },
  { id: 'pg-idx-l4-027', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'GIN Advanced', question: 'What is the "triConsistent" function in GIN (PostgreSQL 9.4+)?', options: ['A triple consistency check', 'A ternary logic function that returns TRUE, FALSE, or MAYBE for candidate rows, allowing GIN to skip heap fetches for definite FALSE', 'A three-way merge function', 'A triple posting list function'], correctAnswer: 1, explanation: 'triConsistent returns FALSE (definitely not a match, skip), TRUE (definitely a match, no recheck needed), or MAYBE (might match, need to recheck by fetching the heap tuple).', tags: ['triconsistent', 'gin', 'ternary-logic'] },
  { id: 'pg-idx-l4-028', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is "index prefetching" and does PostgreSQL support it?', options: ['Always supported', 'PostgreSQL uses effective_io_concurrency to issue prefetch requests for heap pages during bitmap heap scans, overlapping I/O with CPU work', 'Not supported at all', 'Only for sequential scans'], correctAnswer: 1, explanation: 'During bitmap heap scans, PostgreSQL can issue asynchronous read requests for upcoming heap pages. effective_io_concurrency controls how many concurrent requests. Benefits SSDs and RAID.', tags: ['prefetching', 'effective-io-concurrency', 'bitmap-heap'] },
  { id: 'pg-idx-l4-029', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'B-tree Advanced', question: 'What is the "simple deletion" optimization for B-tree LP_DEAD items?', options: ['Simple deletion of rows', 'When an index scan finds a dead TID, it marks the index entry as LP_DEAD; subsequent scans skip it, and it is cleaned up lazily', 'Deleting simple values', 'A fast delete path'], correctAnswer: 1, explanation: 'During index scans, PostgreSQL can mark entries as LP_DEAD when the referenced heap tuple is dead. Future scans skip these entries. VACUUM eventually removes them. This is called "kill" in code.', tags: ['lp-dead', 'simple-deletion', 'lazy-cleanup'] },
  { id: 'pg-idx-l4-030', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is the "upper planner" and how does it interact with indexes?', options: ['A higher-level planner', 'The upper planner handles GROUP BY, HAVING, ORDER BY, LIMIT, and DISTINCT; it considers whether index ordering can satisfy these requirements', 'A planner for upper management', 'The primary planner module'], correctAnswer: 1, explanation: 'The lower planner handles joins and base relations. The upper planner adds grouping, sorting, and limiting on top. If an index provides the right sort order, the upper planner can skip explicit sorts.', tags: ['upper-planner', 'sort-requirements', 'index-ordering'] },
  { id: 'pg-idx-l4-031', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Index Corruption', question: 'What causes index corruption and how do you detect it?', options: ['Corruption is impossible', 'Hardware failures, bugs, or WAL corruption can cause it; detect with amcheck extension\'s bt_index_check() and bt_index_parent_check()', 'Only from DROP TABLE', 'Only from VACUUM'], correctAnswer: 1, explanation: 'Causes: disk errors, memory corruption, filesystem bugs, kernel bugs. Symptoms: wrong query results, crashes. Detection: amcheck, REINDEX finds errors, comparing index and heap data.', tags: ['corruption', 'detection', 'amcheck'] },
  { id: 'pg-idx-l4-032', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'GiST Advanced', question: 'What is the "buffered build" for GiST indexes?', options: ['Building GiST in a buffer', 'A bulk loading strategy that buffers entries in memory and writes complete subtrees at once, reducing random I/O during index creation', 'A staged build process', 'Building with extra memory'], correctAnswer: 1, explanation: 'GiST buffered build (default for large tables) buffers entries at each internal node level, flushing them in bulk. This creates a more balanced tree with less I/O than row-by-row insertion.', codeSnippet: 'CREATE INDEX ON geom_table USING gist (geom)\nWITH (buffering = auto);', tags: ['gist', 'buffered-build', 'bulk-loading'] },
  { id: 'pg-idx-l4-033', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the "parallel-safe" requirement for index operations?', options: ['All indexes are parallel-safe', 'Index operations must not use shared state unsafely; custom index access methods must declare their parallel safety level', 'Only B-tree is parallel-safe', 'Parallel safety is not configurable'], correctAnswer: 1, explanation: 'Index access methods declare their parallel safety. B-tree and BRIN scans are parallel-safe. GIN/GiST have restrictions. Custom access methods must explicitly declare parallel safety.', tags: ['parallel-safe', 'access-method', 'restrictions'] },
  { id: 'pg-idx-l4-034', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is the "eclass" (equivalence class) mechanism\'s role in index selection?', options: ['Classifying indexes', 'Equivalence classes allow the planner to use an index on column B when WHERE A = B AND A = 5, even though the query mentions A, not B', 'Equating index types', 'Comparing index costs'], correctAnswer: 1, explanation: 'When a = b and a = 5, the planner deduces b = 5 via equivalence classes. If there is an index on b but not a, the planner can use the b index. This enables transitive predicate application.', tags: ['eclass', 'transitive', 'index-selection'] },
  { id: 'pg-idx-l4-035', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'B-tree Advanced', question: 'What is "micro vacuum" of B-tree indexes during normal scanning?', options: ['A small vacuum process', 'Index scan operations mark dead entries (LP_DEAD), which are removed opportunistically during page access, without requiring VACUUM', 'Vacuuming small indexes', 'A fast vacuum mode'], correctAnswer: 1, explanation: 'When an index scan encounters a TID pointing to a dead heap tuple, it marks the index entry as LP_DEAD. Subsequent scans on that page can remove these entries, a form of "micro vacuum".', tags: ['micro-vacuum', 'lp-dead', 'opportunistic'] },
  { id: 'pg-idx-l4-036', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the impact of "checkpoint spreading" on index performance?', options: ['No impact', 'During checkpoints, dirty pages (including index pages) are written to disk; checkpoint_completion_target controls how gradually this happens to avoid I/O spikes', 'Checkpoints rebuild indexes', 'Only affects WAL'], correctAnswer: 1, explanation: 'Checkpoints flush all dirty pages. Sudden flushing causes I/O spikes affecting query performance. checkpoint_completion_target (default 0.9) spreads writes over 90% of the checkpoint interval.', tags: ['checkpoint', 'io-spikes', 'spreading'] },
  { id: 'pg-idx-l4-037', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'GIN Advanced', question: 'How does GIN handle index updates without the pending list?', options: ['Each insert is immediate', 'Without fastupdate, each insert immediately adds entries to the main GIN tree, causing many random I/O operations for multi-key values', 'Updates are batched elsewhere', 'GIN does not support immediate inserts'], correctAnswer: 1, explanation: 'Without fastupdate (or after the pending list is flushed), each new JSONB/tsvector value requires inserting entries for every key into the main GIN B-tree. For a 100-key document, that is 100 insertions.', tags: ['gin', 'immediate-insert', 'io-cost'] },
  { id: 'pg-idx-l4-038', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is "qual pushdown to parameterized paths"?', options: ['Pushing quality improvements', 'Moving filter conditions from the join node down to the inner index scan, so they become Index Cond rather than Filter', 'Pushing quality metrics', 'A QA process'], correctAnswer: 1, explanation: 'When the planner creates a parameterized index path, it moves applicable outer-row-dependent conditions into the index condition. This reduces heap fetches vs applying them as post-scan filters.', tags: ['qual-pushdown', 'parameterized', 'index-cond'] },
  { id: 'pg-idx-l4-039', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the "double buffering" problem between PostgreSQL and the OS file cache?', options: ['Not a real problem', 'Data may be cached in both shared_buffers and the OS page cache, wasting memory; mitigated by Direct I/O (PG 16+) or proper OS configuration', 'Double caching improves performance', 'Only affects Windows'], correctAnswer: 1, explanation: 'Without Direct I/O, PostgreSQL reads go through the OS page cache. Data cached in both shared_buffers and OS cache wastes RAM. PG 16+ explores Direct I/O. Some use O_DIRECT via GUC.', tags: ['double-buffering', 'os-cache', 'direct-io'] },
  { id: 'pg-idx-l4-040', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'BRIN Advanced', question: 'What is the trade-off between BRIN and B-tree for time-series data?', options: ['BRIN is always better', 'BRIN is 1000x smaller and faster to build; B-tree provides exact random lookups. BRIN is ideal for append-only time-series with range queries', 'B-tree is always better', 'They perform identically'], correctAnswer: 1, explanation: 'For time-series: BRIN uses ~0.1% of B-tree space, builds instantly, but only supports range queries on correlated data. B-tree supports exact lookups and arbitrary ORDER BY. Choose based on query patterns.', tags: ['brin-vs-btree', 'time-series', 'trade-off'] },
  { id: 'pg-idx-l4-041', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is the "join removal" optimization based on UNIQUE constraints?', options: ['Removing all joins', 'If a LEFT JOIN references a UNIQUE-constrained column and no columns from the joined table are used, the planner can remove the entire join', 'Removing unique values', 'Removing duplicate joins'], correctAnswer: 1, explanation: 'JOIN removal: if LEFT JOIN is on a UNIQUE/PK column and the right table contributes nothing to the result (no columns used, no filtering), the join is provably unnecessary and removed.', tags: ['join-removal', 'unique', 'optimization'] },
  { id: 'pg-idx-l4-042', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Advanced', question: 'What is "index-only delete" (PostgreSQL 16)?', options: ['Deleting only the index', 'Some index access methods can delete entries without visiting the heap table, improving bulk deletion performance', 'Deleting from an index-only view', 'Removing Index Only Scan support'], correctAnswer: 1, explanation: 'Index-only delete allows B-tree VACUUM to remove dead index entries without heap access in certain cases, speeding up the index cleanup phase of VACUUM.', tags: ['index-only-delete', 'vacuum', 'performance'] },
  { id: 'pg-idx-l4-043', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'How does the "ring buffer" strategy affect sequential scan performance on large tables?', options: ['No effect', 'PostgreSQL uses a small ring buffer (256KB) for large sequential scans to prevent evicting cached data, limiting the scan\'s cache pollution', 'Ring buffers slow down scans', 'Only for index scans'], correctAnswer: 1, explanation: 'To prevent a large seq scan from flushing useful data from shared_buffers, PostgreSQL limits the scan to a small ring buffer. This means large seq scans do not benefit from shared_buffers caching.', tags: ['ring-buffer', 'sequential-scan', 'cache-pollution'] },
  { id: 'pg-idx-l4-044', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'GiST Advanced', question: 'What is "ordered GiST scan" (KNN)?', options: ['Sorting GiST entries', 'GiST supports K-Nearest-Neighbor searches via ORDER BY distance using a priority queue to efficiently retrieve the closest matches', 'A GiST scan in order', 'An ordered insertion mode'], correctAnswer: 1, explanation: 'KNN GiST scan uses a priority queue. It explores the closest bounding boxes first, expanding the search radius. Combined with LIMIT, it finds the N nearest neighbors without scanning all entries.', codeSnippet: 'SELECT * FROM places\nORDER BY location <-> point(40.7, -74.0)\nLIMIT 5;', tags: ['knn', 'gist', 'priority-queue'] },
  { id: 'pg-idx-l4-045', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is the "restriction selectivity" vs "join selectivity" of an operator?', options: ['They are the same', 'Restriction selectivity estimates WHERE clause filter fraction; join selectivity estimates the fraction of rows surviving a join condition', 'Restriction is for indexes', 'Join is for subqueries'], correctAnswer: 1, explanation: 'Each operator has two selectivity estimator functions. Restriction selectivity (e.g., = is 1/n_distinct). Join selectivity (e.g., = is 1/max(n_distinct_a, n_distinct_b)). Custom operators need both.', tags: ['selectivity-functions', 'restriction', 'join'] },
  { id: 'pg-idx-l4-046', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'B-tree Advanced', question: 'What is the "integer overflow" issue with B-tree page recycling?', options: ['Not a real issue', 'Recycled B-tree pages might be reused before all in-flight scans complete; PostgreSQL uses "safexid" to prevent accessing stale page contents', 'Integer overflow in key values', 'Counter overflow in index'], correctAnswer: 1, explanation: 'B-tree uses a "safexid" mechanism to prevent recycled pages from being reused while old transactions might still access them. This prevents data corruption from stale page reads.', tags: ['page-recycling', 'safexid', 'concurrency-safety'] },
  { id: 'pg-idx-l4-047', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the "TidScan" optimization for ctid-based queries?', options: ['A regular index scan', 'A specialized scan that directly accesses heap pages by ctid, used for self-referencing updates and internal operations', 'A scan for TID data type', 'A text ID scan'], correctAnswer: 1, explanation: 'TidScan directly fetches heap tuples by physical address. Used internally for CurrentOfExpr (WHERE CURRENT OF cursor) and explicit ctid queries. It is O(1) per tuple access.', tags: ['tid-scan', 'ctid', 'direct-access'] },
  { id: 'pg-idx-l4-048', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'GIN Advanced', question: 'What is the GIN "posting tree" threshold?', options: ['The maximum posting size', 'When a posting list exceeds one index page, it is converted to a posting tree (B-tree of TIDs) for efficient O(log N) lookup and update', 'The minimum posting size', 'A tuning parameter'], correctAnswer: 1, explanation: 'Small posting lists are stored inline (one page). When a key has many matching rows (popular value), the posting list becomes a B-tree of TIDs, enabling efficient position-based lookups.', tags: ['gin', 'posting-tree', 'threshold'] },
  { id: 'pg-idx-l4-049', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Advanced', question: 'What are "columnar indexes" and does PostgreSQL support them natively?', options: ['Yes, via column-oriented indexes', 'PostgreSQL does not have native columnar indexes, but extensions like cstore_fdw/Citus columnar and BRIN + INCLUDE approximate some benefits', 'B-tree is columnar', 'Only with GIN'], correctAnswer: 1, explanation: 'PostgreSQL is row-oriented. For analytics, BRIN on correlated columns plus covering indexes approximate columnar benefits. Full columnar support requires extensions or Citus columnar.', tags: ['columnar', 'analytics', 'extensions'] },
  { id: 'pg-idx-l4-050', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'How does the planner handle "non-hashable" data types in semi-join optimization?', options: ['It cannot optimize semi-joins', 'If the data type does not support hashing, the planner falls back to nested loop or merge join strategies for EXISTS/IN instead of hash semi-join', 'It uses B-tree instead', 'It creates a temporary hash'], correctAnswer: 1, explanation: 'Hash semi-join requires the data type to have a hash function. For types without one (e.g., complex composite types), the planner must use nested loop or merge semi-join.', tags: ['non-hashable', 'semi-join', 'fallback'] },
  { id: 'pg-idx-l4-051', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the "wal_compression" setting and how does it interact with index writes?', options: ['Compressing the index', 'Compresses full-page images in WAL, reducing WAL volume especially after checkpoints when many index pages generate full-page writes', 'Compressing WAL files', 'Compressing table data'], correctAnswer: 1, explanation: 'After checkpoints, first modifications to pages write full page images to WAL. wal_compression compresses these images, reducing WAL volume by 30-50%. Especially beneficial for index-heavy workloads.', codeSnippet: 'ALTER SYSTEM SET wal_compression = \'lz4\'; -- or zstd, pglz', tags: ['wal-compression', 'full-page-writes', 'io-reduction'] },
  { id: 'pg-idx-l4-052', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Index Design', question: 'What is the "exclusion constraint" index strategy for temporal data?', options: ['Excluding data from the index', 'Using GiST indexes with range types to prevent overlapping time intervals, implementing business rules at the database level', 'A special index type', 'Excluding NULLs from the index'], correctAnswer: 1, explanation: 'Exclusion constraints with GiST enforce that no two rows have overlapping ranges (e.g., meeting room bookings). The GiST index efficiently checks for conflicts during INSERT/UPDATE.', codeSnippet: 'CREATE TABLE bookings (\n  room_id INT,\n  during TSRANGE,\n  EXCLUDE USING GIST (\n    room_id WITH =,\n    during WITH &&\n  )\n);', tags: ['exclusion-constraint', 'temporal', 'gist'] },
  { id: 'pg-idx-l4-053', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is the "eqjoinsel" vs "neqjoinsel" selectivity estimator?', options: ['Equal and not-equal selectors', 'eqjoinsel estimates the fraction of rows matching an equality join (≈ 1/max(ndistinct)); neqjoinsel estimates non-equality (≈ 1 - 1/max(ndistinct))', 'They are PostgreSQL internals', 'They estimate query execution time'], correctAnswer: 1, explanation: 'eqjoinsel: for a = b, estimates ≈ 1/max(ndistinct_a, ndistinct_b). neqjoinsel: for a != b, estimates ≈ 1 - 1/max(ndistinct_a, ndistinct_b). These directly affect join output row estimates.', tags: ['eqjoinsel', 'selectivity', 'planner-internals'] },
  { id: 'pg-idx-l4-054', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is "IO concurrency" and how does it benefit index scans on modern storage?', options: ['Running queries concurrently', 'Issuing multiple asynchronous I/O requests simultaneously to take advantage of SSD/NVMe parallelism for heap page fetches', 'Concurrent index builds', 'Parallel I/O workers'], correctAnswer: 1, explanation: 'NVMe SSDs can handle hundreds of concurrent I/O requests. effective_io_concurrency tells PostgreSQL to issue multiple prefetch requests during bitmap heap scans, fully utilizing SSD bandwidth.', tags: ['io-concurrency', 'nvme', 'prefetch'] },
  { id: 'pg-idx-l4-055', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Advanced', question: 'What is the "equalimage" B-tree support function (PostgreSQL 13)?', options: ['An image equality function', 'A function that tells PostgreSQL whether the index datum is a perfect copy of the heap datum, enabling deduplication safely', 'An image comparison function', 'A visual diff function'], correctAnswer: 1, explanation: 'The equalimage function indicates whether the B-tree can safely use deduplication for a data type. Some types (like numeric with trailing zeros) may have different representations for equal values.', tags: ['equalimage', 'deduplication', 'safety'] },
  { id: 'pg-idx-l4-056', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Index Design', question: 'What is the "covering unique constraint" pattern for denormalized data?', options: ['A constraint that covers all columns', 'Using INCLUDE on a UNIQUE index to add frequently accessed columns for Index Only Scan without affecting the uniqueness guarantee', 'A full-table unique constraint', 'Covering all foreign keys'], correctAnswer: 1, explanation: 'A UNIQUE index with INCLUDE adds non-key columns for covering purposes. The uniqueness is enforced only on the key columns, but the included columns enable Index Only Scans.', codeSnippet: 'CREATE UNIQUE INDEX idx_email ON users (email)\nINCLUDE (name, active);', tags: ['covering-unique', 'include', 'index-only'] },
  { id: 'pg-idx-l4-057', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is "MCV join selectivity estimation"?', options: ['Joining MCV lists', 'Matching most-common-values lists from both join columns to precisely estimate the number of matching rows for common values', 'A selectivity for MCV columns', 'Most common value filtering'], correctAnswer: 1, explanation: 'The planner matches MCV lists from both sides of a join. For common values that appear in both MCVs, it computes exact match fractions. For remaining values, it uses histogram-based estimates.', tags: ['mcv-join', 'selectivity', 'precise-estimation'] },
  { id: 'pg-idx-l4-058', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the "CPU cache line" effect on B-tree performance?', options: ['No effect', 'B-tree pages are read in OS pages (8KB), but CPU works in cache lines (64B). Dense index entries that fit more keys per cache line have fewer cache misses', 'Cache lines only affect table scans', 'Only for in-memory databases'], correctAnswer: 1, explanation: 'When traversing B-tree internal pages, the CPU accesses entries sequentially. Smaller entries mean more fit per CPU cache line (64B), reducing cache misses and improving traversal speed.', tags: ['cpu-cache-line', 'micro-optimization', 'entry-size'] },
  { id: 'pg-idx-l4-059', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Advanced', question: 'What is the "amcheck" extension\'s bt_index_parent_check and when should you use it?', options: ['A simple consistency check', 'A thorough verification that checks parent-child relationships between B-tree pages, detecting corruption that bt_index_check might miss', 'A parent table check', 'A permission check'], correctAnswer: 1, explanation: 'bt_index_parent_check performs cross-level validation: verifying that parent page entries correctly reference child pages. It is slower but catches more types of corruption. Use after suspected issues.', codeSnippet: 'SELECT bt_index_parent_check(\'idx_users_email\', true); -- true = heapkeyspace check', tags: ['amcheck', 'parent-check', 'thorough-verification'] },
  { id: 'pg-idx-l4-060', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'GIN Advanced', question: 'What is the performance impact of gin_fuzzy_search_limit?', options: ['No impact', 'It limits the maximum number of results from a GIN scan, trading accuracy for speed on very common terms', 'It limits fuzzy matching distance', 'It limits GIN index size'], correctAnswer: 1, explanation: 'gin_fuzzy_search_limit (default 0 = unlimited) caps the number of results from a GIN index scan. For common terms matching millions of rows, this trades completeness for dramatically faster response.', codeSnippet: 'SET gin_fuzzy_search_limit = 10000;', tags: ['gin-fuzzy-limit', 'performance', 'trade-off'] },
  { id: 'pg-idx-l4-061', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What role does "reltuples" and "relpages" play in index cost estimation?', options: ['They are for display only', 'reltuples = estimated row count, relpages = estimated page count in pg_class; the planner uses these as base numbers for all cost calculations', 'They track real-time counts', 'They are lock counters'], correctAnswer: 1, explanation: 'pg_class.reltuples and relpages are updated by ANALYZE/VACUUM. All cost estimates derive from these. Stale values (after massive data changes without ANALYZE) cause bad plans.', tags: ['reltuples', 'relpages', 'cost-basis'] },
  { id: 'pg-idx-l4-062', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Advanced', question: 'What is "index-only count" vs "heap count" for SELECT COUNT(*)?', options: ['They are the same', 'Index-only count uses Index Only Scan on a small index; heap count seq-scans the table. Index-only is faster if the index is smaller and well-vacuumed', 'Index count is always faster', 'Heap count is always faster'], correctAnswer: 1, explanation: 'For COUNT(*) with a WHERE clause matching an indexed column, Index Only Scan on a small index avoids reading the entire (possibly larger) heap. Requires good visibility map (recent VACUUM).', tags: ['index-only-count', 'heap-count', 'performance'] },
  { id: 'pg-idx-l4-063', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is "IO uring" support in PostgreSQL and how might it affect index performance?', options: ['Not related to PostgreSQL', 'IO uring is a Linux async I/O API; PostgreSQL is exploring it for efficient asynchronous page reads during index/heap scans', 'A PostgreSQL extension', 'A connection pooling technique'], correctAnswer: 1, explanation: 'io_uring provides efficient asynchronous I/O on Linux. PostgreSQL is investigating its use for prefetching and async reads, which could significantly improve random I/O-heavy index scan performance.', tags: ['io-uring', 'async-io', 'future'] },
  { id: 'pg-idx-l4-064', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'B-tree Advanced', question: 'What is the "incomplete split" handling in B-tree concurrent access?', options: ['A split that failed', 'When a page split crashes mid-way, the right-link allows readers to find the new page while the split completes during recovery', 'An index corruption', 'A partial index build'], correctAnswer: 1, explanation: 'Lehman-Yao B-tree: if a crash occurs during a page split, the right-link ensures readers can still navigate. During recovery, the incomplete split is detected and finished.', tags: ['incomplete-split', 'crash-recovery', 'lehman-yao'] },
  { id: 'pg-idx-l4-065', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is "index correlation" in pg_stats and how does the planner use it?', options: ['How correlated index columns are', 'The statistical correlation between physical row order and index order; high correlation reduces the estimated random I/O cost of index scans', 'Correlation between indexes', 'Index usage correlation'], correctAnswer: 1, explanation: 'correlation ≈ 1 means data is physically sorted like the index. The planner reduces the random_page_cost multiplier for high-correlation indexes because sequential I/O patterns emerge.', tags: ['correlation', 'random-io', 'cost-reduction'] },
  { id: 'pg-idx-l4-066', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Advanced', question: 'What is "summarizing BRIN" vs "non-summarizing BRIN" and how does autosummarize help?', options: ['They are the same', 'Non-summarized ranges return no results for BRIN queries; autosummarize (PG 11+) automatically summarizes new page ranges in the background', 'BRIN always summarizes immediately', 'Manual summarization only'], correctAnswer: 1, explanation: 'New heap pages are not included in BRIN summaries until summarized. Without autosummarize, recent data may not benefit from BRIN filtering until manual summarization or VACUUM.', tags: ['brin', 'autosummarize', 'new-data'] },
  { id: 'pg-idx-l4-067', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the relationship between "WAL full page writes" and index performance?', options: ['No relationship', 'After each checkpoint, the first change to every index page writes the full 8KB page to WAL, significantly increasing WAL volume for index-heavy workloads', 'WAL only logs data pages', 'Full page writes improve index speed'], correctAnswer: 1, explanation: 'full_page_writes after checkpoints are a major source of WAL volume for indexes. Many small index updates each trigger a full 8KB page write. wal_compression and longer checkpoint intervals help.', tags: ['full-page-writes', 'wal-volume', 'checkpoint'] },
  { id: 'pg-idx-l4-068', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'GiST Advanced', question: 'What is the "sortsupport" function for GiST index builds?', options: ['Sorting GiST entries', 'A function that provides comparison support for pre-sorting data before bulk GiST index construction, improving index quality', 'Supporting sort operations', 'A sort order for GiST scans'], correctAnswer: 1, explanation: 'For certain GiST operator classes (like for points), a sortsupport function enables pre-sorting data before building the index, producing a more balanced tree with less overlap.', tags: ['gist', 'sortsupport', 'build-quality'] },
  { id: 'pg-idx-l4-069', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Index Design', question: 'What is the optimal strategy for indexing a "soft delete" pattern with deleted_at column?', options: ['Index on deleted_at', 'Partial index WHERE deleted_at IS NULL for active queries; separate partial index WHERE deleted_at IS NOT NULL for audit queries', 'Full index on deleted_at and id', 'No indexing needed'], correctAnswer: 1, explanation: 'Most queries filter active records (deleted_at IS NULL). A partial index on the columns you filter/sort by WHERE deleted_at IS NULL keeps the index small and fast for the common case.', codeSnippet: 'CREATE INDEX idx_active_users_email\nON users (email)\nWHERE deleted_at IS NULL;', tags: ['soft-delete', 'partial-index', 'strategy'] },
  { id: 'pg-idx-l4-070', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is the "foreign key join estimation" optimization?', options: ['Estimating FK performance', 'The planner uses FK constraints to improve join cardinality estimates, knowing that each child row has exactly one matching parent', 'FK indexes are used for estimation', 'Estimating FK overhead'], correctAnswer: 1, explanation: 'FK constraints tell the planner the relationship cardinality. For a FK from orders.user_id to users.id, the planner knows every order row matches exactly one user, improving estimates.', tags: ['fk-estimation', 'cardinality', 'planner'] },
  { id: 'pg-idx-l4-071', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is "parallel B-tree vacuum" (PostgreSQL 13+)?', options: ['Vacuuming B-trees in parallel', 'VACUUM can use parallel workers to clean multiple indexes simultaneously, reducing total VACUUM time for tables with many indexes', 'Parallel B-tree builds', 'B-tree deduplication'], correctAnswer: 1, explanation: 'VACUUM with max_parallel_maintenance_workers > 0 can clean multiple indexes in parallel during the index cleanup phase. This significantly reduces VACUUM time for tables with many indexes.', codeSnippet: 'VACUUM (PARALLEL 4) big_table;', tags: ['parallel-vacuum', 'index-cleanup', 'postgresql-13'] },
  { id: 'pg-idx-l4-072', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Advanced', question: 'What is the "ScalarArrayOpExpr" optimization for IN lists with B-tree indexes?', options: ['A scalar operation', 'For WHERE col IN (1,2,3), PostgreSQL performs a sorted array lookup against the B-tree, visiting each value efficiently without multiple index scans', 'Array operations on indexes', 'Scalar comparison in indexes'], correctAnswer: 1, explanation: 'ScalarArrayOpExpr sorts the IN list and performs a single index scan that efficiently jumps to each value. This is much faster than N separate index scans for large IN lists.', tags: ['scalar-array-op', 'in-list', 'single-scan'] },
  { id: 'pg-idx-l4-073', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'How does the planner handle "type-mismatch" between a query value and an indexed column?', options: ['It casts automatically', 'If the WHERE value type does not match the indexed column type, the planner may not use the index unless there is an implicit cast or cross-type operator', 'It always uses the index', 'It raises an error'], correctAnswer: 1, explanation: 'For WHERE bigint_col = 42 (integer literal), PostgreSQL has cross-type operators. But WHERE text_col = 42 may not use the text index because there is no text = int operator.', tags: ['type-mismatch', 'cross-type-operator', 'implicit-cast'] },
  { id: 'pg-idx-l4-074', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the "parallel index scan" limitation and when does the planner prefer parallel seq scan?', options: ['No limitations', 'Parallel index scans have synchronization overhead; for low selectivity queries, parallel seq scan divides pages evenly and can be faster', 'Index scans cannot be parallel', 'Seq scans cannot be parallel'], correctAnswer: 1, explanation: 'Parallel index scans must coordinate between workers (which index pages to scan next). For queries returning many rows, parallel seq scan with simple page-division can have higher throughput.', tags: ['parallel-limitation', 'coordination', 'seq-vs-index'] },
  { id: 'pg-idx-l4-075', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Advanced', question: 'What is the "index predicate locking" granularity for serializable transactions?', options: ['Entire index lock', 'Predicate locks are taken at the page level for index scans and at the relation level for sequential scans', 'Per-row locking', 'No locking'], correctAnswer: 1, explanation: 'In SERIALIZABLE isolation, index scans create page-level SIRead locks on accessed index pages. Seq scans create relation-level locks. More granular (index) locks reduce false-positive serialization failures.', tags: ['predicate-lock', 'serializable', 'granularity'] },
  { id: 'pg-idx-l4-076', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'GIN Advanced', question: 'What is the impact of GIN "posting list compression" on performance?', options: ['No compression exists', 'GIN compresses posting lists using varbyte encoding, reducing index size and improving cache efficiency for common terms', 'Compression slows down queries', 'Only available for JSONB'], correctAnswer: 1, explanation: 'GIN posting lists use varbyte (variable-byte) encoding to store TID differences compactly. This reduces index size significantly for popular keys, improving I/O and cache performance.', tags: ['gin', 'posting-compression', 'varbyte'] },
  { id: 'pg-idx-l4-077', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is "partial aggregation pushdown" and how does it interact with indexes?', options: ['Partially aggregating index entries', 'In parallel queries, partial aggregation is done in workers; if an index provides sorted input, the aggregation can use sorted grouping instead of hashing', 'Pushing aggregates into indexes', 'A type of index scan'], correctAnswer: 1, explanation: 'When an index provides data sorted by GROUP BY columns, parallel workers can perform sorted partial aggregation, which is streamed to the leader for finalization. No hash table needed.', tags: ['partial-aggregation', 'sorted-grouping', 'parallel'] },
  { id: 'pg-idx-l4-078', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the "proactive background vacuum" concept for indexes?', options: ['Vacuuming in the background', 'Autovacuum proactively cleans indexes when dead tuple count exceeds thresholds, preventing gradual performance degradation', 'A future PostgreSQL feature', 'Manual vacuum scheduling'], correctAnswer: 1, explanation: 'Autovacuum monitors n_dead_tup and triggers when it exceeds autovacuum_vacuum_threshold + autovacuum_vacuum_scale_factor × reltuples. This prevents index bloat from accumulating.', tags: ['autovacuum', 'proactive', 'thresholds'] },
  { id: 'pg-idx-l4-079', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Index Design', question: 'What is the "index-advisory-locking" pattern for queue tables?', options: ['Locking index entries', 'Using advisory locks with index-based dequeue: FOR UPDATE SKIP LOCKED uses the index to find and lock work items efficiently', 'Index-based locks', 'Locking the index during reads'], correctAnswer: 1, explanation: 'For job queue tables: SELECT ... WHERE status = \'pending\' ORDER BY priority LIMIT 1 FOR UPDATE SKIP LOCKED uses a partial index on (priority) WHERE status = \'pending\' for efficient dequeue.', codeSnippet: 'CREATE INDEX idx_pending_jobs ON jobs (priority)\nWHERE status = \'pending\';\n\nSELECT * FROM jobs\nWHERE status = \'pending\'\nORDER BY priority\nLIMIT 1\nFOR UPDATE SKIP LOCKED;', tags: ['queue', 'skip-locked', 'partial-index'] },
  { id: 'pg-idx-l4-080', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Advanced', question: 'What is "cross-column statistics" (PG 14+ MCV)?', options: ['Statistics on cross joins', 'Extended statistics that store multi-column most-common-values, improving estimates for multi-column conditions', 'Cross-referencing column stats', 'Statistics across tables'], correctAnswer: 1, explanation: 'PG 14 added multi-column MCV (most-common-values) to CREATE STATISTICS. This captures which combinations of values frequently occur together, dramatically improving correlated column estimates.', codeSnippet: 'CREATE STATISTICS mcv_stats (mcv)\nON city, state, zip FROM addresses;\nANALYZE addresses;', tags: ['multi-column-mcv', 'extended-statistics', 'postgresql-14'] },
  { id: 'pg-idx-l4-081', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is the "one-time filter" in EXPLAIN output?', options: ['A filter applied once', 'A constant condition (like 1=1 or FALSE) that is evaluated once rather than per row, often from constant subquery results', 'A first-row filter', 'A filter on the first scan'], correctAnswer: 1, explanation: 'One-time filters are constant boolean conditions. "One-Time Filter: false" means the entire subtree is skipped. "One-Time Filter: $0" references a pre-computed InitPlan result.', tags: ['one-time-filter', 'constant-condition', 'explain'] },
  { id: 'pg-idx-l4-082', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'What is the relationship between "huge_pages" and index-heavy OLTP workload performance?', options: ['No relationship', 'Huge pages reduce TLB misses for large shared_buffers, which is critical for OLTP workloads with many random index page accesses', 'Huge pages slow down OLTP', 'Only for OLAP workloads'], correctAnswer: 1, explanation: 'OLTP workloads with many concurrent sessions accessing different index pages cause frequent TLB misses. Huge pages (2MB) reduce the TLB entries needed, improving random access performance by 5-15%.', tags: ['huge-pages', 'oltp', 'tlb-misses'] },
  { id: 'pg-idx-l4-083', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Advanced', question: 'What is "index-organized table" emulation using a covering index in PostgreSQL?', options: ['Not possible', 'A covering index with INCLUDE that contains all table columns essentially stores all data in index order, approximating an IOT', 'Using CLUSTER only', 'Using materialized views'], correctAnswer: 1, explanation: 'A covering index with all columns stores sorted data that can satisfy any query via Index Only Scan. However, it doubles storage and write overhead, making it impractical for most use cases.', tags: ['iot-emulation', 'covering-all', 'trade-off'] },
  { id: 'pg-idx-l4-084', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Index Design', question: 'What is the "index for foreign key enforcement" performance consideration?', options: ['FK enforcement does not use indexes', 'FK checks query the referenced table during child INSERT and the referencing table during parent UPDATE/DELETE; indexes on both sides are critical', 'Only the parent needs an index', 'Only the child needs an index'], correctAnswer: 1, explanation: 'FK validation: child INSERT checks parent existence (needs PK index on parent). Parent UPDATE/DELETE checks for dependent children (needs FK column index on child). Missing child-side index causes seq scans.', tags: ['fk-enforcement', 'both-indexes', 'performance'] },
  { id: 'pg-idx-l4-085', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Planner Internals', question: 'What is the "cheapest_total" vs "cheapest_startup" path selection?', options: ['Total cost is always chosen', 'The planner maintains both: cheapest_total for full scans and cheapest_startup for LIMIT/cursor queries that need first rows fast', 'Startup is always faster', 'They produce the same plan'], correctAnswer: 1, explanation: 'For full result sets, cheapest_total wins (e.g., hash join). For LIMIT queries, cheapest_startup wins (e.g., nested loop with index). The planner keeps both paths for different contexts.', tags: ['cheapest-total', 'cheapest-startup', 'context-dependent'] },
  { id: 'pg-idx-l4-086', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Performance', question: 'How does "connection pooling" interact with prepared statements and custom vs generic plans?', options: ['No interaction', 'Connection poolers may reuse sessions with different parameters; statement-level poolers reset prepared statements, while session-level poolers preserve them', 'Pooling disables prepared statements', 'Pooling always uses generic plans'], correctAnswer: 1, explanation: 'Transaction-level pooling (PgBouncer default) resets session state including prepared statements. This forces re-planning each time. Session-level pooling preserves plans but limits concurrency.', tags: ['connection-pooling', 'prepared-statements', 'plan-caching'] },
  { id: 'pg-idx-l4-087', language: 'postgresql', level: 'level4', category: 'Indexes & Performance', subcategory: 'Advanced', question: 'What is the "pg_qualstats" extension and how does it help with index design?', options: ['A quality statistics tool', 'It tracks which WHERE clause conditions are executed and their selectivity, suggesting optimal indexes based on actual workload', 'A query stats extension', 'A plan quality monitor'], correctAnswer: 1, explanation: 'pg_qualstats records every WHERE clause predicate with its execution count and selectivity. Combined with pg_stat_statements, it provides data-driven index recommendations based on real workload patterns.', codeSnippet: 'CREATE EXTENSION pg_qualstats;\n-- After running workload:\nSELECT * FROM pg_qualstats_indexes(); -- Suggested indexes', tags: ['pg-qualstats', 'index-recommendation', 'workload-analysis'] },
];

